// NewListResponseBody builds the HTTP response body from the result of the
// "list" endpoint of the "boards" service.
func NewListResponseBody(res []*boards.BoardSummary) []*BoardSummaryResponse {
	body := make([]*BoardSummaryResponse, len(res))
	for i, val := range res {
		if val == nil {
			body[i] = nil
			continue
		}
		body[i] = marshalBoardsBoardSummaryToBoardSummaryResponse(val)
	}
	return body
}

// NewGetResponseBody builds the HTTP response body from the result of the
// "get" endpoint of the "boards" service.
