// ValidateAddStickyRequestBody runs the validations defined on
// AddStickyRequestBody
func ValidateAddStickyRequestBody(body *AddStickyRequestBody) (err error) {
	if body.Anchor == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("anchor", "body"))
	}
	if body.Kind == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("kind", "body"))
	}
	if body.Parent != nil {
		err = goa.MergeErrors(err, goa.ValidatePattern("body.parent", *body.Parent, "^s[0-9a-f]{8}$"))
	}
	if body.Anchor != nil {
		if err2 := validateBoardAnchorRequestBody(body.Anchor, "body.anchor"); err2 != nil {
			err = goa.MergeErrors(err, err2)
		}
	}
	if body.Kind != nil {
		if !(*body.Kind == "memo" || *body.Kind == "assistant" || *body.Kind == "fork") {
			err = goa.MergeErrors(err, goa.InvalidEnumValueError("body.kind", *body.Kind, []any{"memo", "assistant", "fork"}))
		}
	}
	if body.Text != nil {
		if utf8.RuneCountInString(*body.Text) > 10240 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.text", *body.Text, utf8.RuneCountInString(*body.Text), 10240, false))
		}
	}
	return
}

